window.fitInstanceGraph=function(){if(!instanceGraphSvg||!document.body.contains(instanceGraphSvg))return;var nodes=instanceVisibleGraph().nodes,box=instanceGraphSvg.viewBox.baseVal;if(!nodes.length){instanceGraphView={x:0,y:0,k:1};return applyInstanceGraphView()}var minX=Math.min.apply(null,nodes.map(function(node){return node.x-node.radius-30})),maxX=Math.max.apply(null,nodes.map(function(node){return node.x+node.radius+30})),minY=Math.min.apply(null,nodes.map(function(node){return node.y-node.radius-30})),maxY=Math.max.apply(null,nodes.map(function(node){return node.y+node.radius+30})),scale=Math.min(box.width/Math.max(maxX-minX,1),box.height/Math.max(maxY-minY,1),1.6)*.9;instanceGraphView={k:Math.max(.3,scale),x:(box.width-(minX+maxX)*scale)/2,y:(box.height-(minY+maxY)*scale)/2};applyInstanceGraphView();updateInstanceGraphDOM()};
