function workflowProgress(row){if(row.status==='COMPLETED')return 8;var completed=Number(row.completed_steps||0),skipped=Number(row.skipped_steps||0);return Math.min(8,completed+skipped)}
function workflowEntryLabel(value){return value==='NEW'?'新申请进件':'已有申请续办'}
function renderWorkflowSummary(summary){var completed=(summary.by_status||{}).COMPLETED||0;return '<div class="workflow-summary-grid"><div class="workflow-metric"><span>流程总数</span><b>'+(summary.total||0)+'</b><small>全部申请流程</small></div><div class="workflow-metric accent"><span>待处理</span><b>'+(summary.active||0)+'</b><small>需要继续推进</small></div><div class="workflow-metric"><span>可执行步骤</span><b>'+(summary.ready_steps||0)+'</b><small>当前业务待办</small></div><div class="workflow-metric success"><span>已完成</span><b>'+completed+'</b><small>已形成建议闭环</small></div></div>'}
function workflowListCard(row){var progress=workflowProgress(row),percent=Math.round(progress/8*100),selected=liveWorkflow&&liveWorkflow.workflow&&liveWorkflow.workflow.workflow_id===row.workflow_id,completed=row.status==='COMPLETED',time=row.completed_at||row.updated_at;return '<button type="button" class="workflow-list-card'+(selected?' selected':'')+(completed?' completed':'')+'" data-workflow-id="'+esc(row.workflow_id)+'" onclick="openWorkflow(\''+esc(row.workflow_id)+'\')"><div class="workflow-list-card-head"><div><span class="workflow-app-id">'+esc(row.application_id)+'</span><small>'+esc(workflowEntryLabel(row.entry_mode))+'</small></div>'+workflowStatusTag(row.status)+'</div><div class="workflow-list-progress"><div><span>'+(completed?'完成进度':'业务进度')+'</span><b>'+progress+' / 8</b></div><div class="workflow-progress-track"><i style="width:'+percent+'%"></i></div></div><div class="workflow-list-card-foot"><span>'+(completed?'完成于 ':'')+esc(formatRuntimeTime(time))+'</span><span>'+(completed?'查看结果':'查看流程')+' <b>→</b></span></div></button>'}
window.filterWorkflowList=function(){var query=(document.getElementById('workflow-search')&&document.getElementById('workflow-search').value||'').trim().toLowerCase(),status=document.getElementById('workflow-status-filter')&&document.getElementById('workflow-status-filter').value||'',count=document.getElementById('workflow-completed-count');if(count)count.textContent=workflowCompletedTotal;var rows=workflowRows.filter(function(row){return (workflowListMode!=='completed'||row.status==='COMPLETED')&&(!query||String(row.application_id||'').toLowerCase().indexOf(query)>=0)&&(!status||row.status===status)}),el=document.getElementById('workflow-list-grid');if(!el)return;el.innerHTML=rows.length?rows.map(workflowListCard).join(''):workflowListMode==='completed'?'<div class="workflow-empty-list"><b>暂无已完成流程</b><span>八个业务步骤全部结束后，流程会保留在这里供查看。</span></div>':'<div class="workflow-empty-list"><b>没有匹配的信审流程</b><span>调整筛选条件，或在上方发起新流程。</span></div>'};
window.setWorkflowListMode=function(mode){workflowListMode=mode==='completed'?'completed':'all';if(workflowListMode==='completed'&&liveWorkflow&&liveWorkflow.workflow&&liveWorkflow.workflow.status!=='COMPLETED')liveWorkflow=null;renderWorkflows()};
window.syncWorkflowEntryHelp=function(){var select=document.getElementById('workflow-entry'),help=document.getElementById('workflow-entry-help');if(!select||!help)return;help.textContent=select.value==='NEW'?'从创建贷款申请开始，基础资料将在第 1 步录入。':'申请须已存在，流程从征信与反欺诈查询开始。'};
async function renderWorkflows(){
  if(workflowPollTimer){clearTimeout(workflowPollTimer);workflowPollTimer=null}
  var selected=liveWorkflow&&liveWorkflow.workflow&&liveWorkflow.workflow.workflow_id,el=document.getElementById('runtime-body');
  el.innerHTML='<div class="workflow-hero"><div><div class="workflow-kicker">PERSONAL CREDIT · 8 ACTIONS</div><h2>个人信审流程</h2><p>沿真实业务依赖逐步推进申请，从进件、征信和风控核验，到人工复核与决策建议。</p></div><div class="workflow-boundary"><b>审批边界</b><span>流程终点仅记录决策建议，不代表最终审批。</span></div></div><section class="card workflow-create-card"><div class="workflow-section-title"><div><h3>发起信审</h3><p>选择申请入口并填写唯一申请编号</p></div><span class="workflow-step-count">8 个业务步骤</span></div><div class="workflow-create-grid"><div class="workflow-control"><label for="workflow-app">申请编号</label><input id="workflow-app" autocomplete="off" maxlength="32" placeholder="例如 APP202608260001"></div><div class="workflow-control"><label for="workflow-entry">流程入口</label><select id="workflow-entry" onchange="syncWorkflowEntryHelp()"><option value="EXISTING">已有申请续办</option><option value="NEW">新申请进件</option></select></div><button id="workflow-create-button" class="btn btn-primary workflow-create-button" onclick="startWorkflow()">创建并进入流程</button></div><p id="workflow-entry-help" class="workflow-inline-help">申请须已存在，流程从征信与反欺诈查询开始。</p></section><div id="workflow-summary" class="workflow-summary-skeleton"></div><div class="workflow-dashboard"><section class="card workflow-list-panel"><div class="workflow-list-toolbar"><div class="workflow-list-heading"><div><h3>申请队列</h3><p>按申请编号定位，并可回看已完成流程的八步结果</p></div><div class="workflow-view-tabs" role="group" aria-label="流程查看范围"><button type="button" data-workflow-mode="all" class="workflow-view-tab'+(workflowListMode==='all'?' on':'')+'" onclick="setWorkflowListMode(\'all\')">全部流程</button><button type="button" data-workflow-mode="completed" class="workflow-view-tab'+(workflowListMode==='completed'?' on':'')+'" onclick="setWorkflowListMode(\'completed\')">已完成 <span id="workflow-completed-count">0</span></button></div></div><div class="workflow-filter-row"><input id="workflow-search" oninput="filterWorkflowList()" placeholder="搜索申请编号" aria-label="搜索申请编号"><select id="workflow-status-filter" onchange="filterWorkflowList()" aria-label="筛选流程状态"'+(workflowListMode==='completed'?' disabled':'')+'><option value="">全部状态</option><option value="WAITING_INPUT">待处理</option><option value="RUNNING">执行中</option><option value="FAILED">需处理</option><option value="COMPLETED"'+(workflowListMode==='completed'?' selected':'')+'>已完成</option><option value="CANCELLED">已取消</option></select><button class="btn btn-sm" onclick="renderWorkflows()" aria-label="刷新申请队列">刷新</button></div></div><div id="workflow-list-grid" class="workflow-list-grid"><div class="workflow-empty-list">正在读取申请队列…</div></div></section><section id="workflow-detail" class="workflow-detail-panel"><div class="workflow-detail-empty"><div class="workflow-empty-mark">8</div><b>选择一笔申请查看流程</b><span>这里会显示当前待办、八步进度和关键业务结果。</span></div></section></div>';
  try{
    var listPath='/workflows/personal-credit?limit=100'+(workflowListMode==='completed'?'&status=COMPLETED':''),values=await Promise.all([api('/workflows/personal-credit/summary'),api(listPath)]),summary=values[0];workflowRows=values[1].workflows||[];workflowCompletedTotal=Number((summary.by_status||{}).COMPLETED||0);
    document.getElementById('workflow-summary').innerHTML=renderWorkflowSummary(summary);filterWorkflowList();
    var selectedRow=workflowRows.find(function(row){return row.workflow_id===selected});if(selectedRow&&(workflowListMode!=='completed'||selectedRow.status==='COMPLETED'))await openWorkflow(selected);else if(workflowListMode==='completed'){var firstCompleted=workflowRows.find(function(row){return row.status==='COMPLETED'});if(firstCompleted)await openWorkflow(firstCompleted.workflow_id)}
  }catch(e){showRuntimeError(e)}
}
window.startWorkflow=async function(){if(workflowLoading)return;var input=document.getElementById('workflow-app'),button=document.getElementById('workflow-create-button');try{var application=(input&&input.value||'').trim(),entry=document.getElementById('workflow-entry').value;if(!/^[A-Za-z0-9][A-Za-z0-9_-]{2,31}$/.test(application))throw new Error('申请编号需为 3–32 位字母、数字、下划线或连字符');workflowLoading=true;if(button){button.disabled=true;button.textContent='正在创建…'}var data=await api('/workflows/personal-credit',{method:'POST',body:body({application_id:application,entry_mode:entry,request_id:requestId('workflow')})}),id=data.workflow_id||(data.workflow&&data.workflow.workflow_id);toast('流程已创建，可以开始处理','ok');workflowListMode='all';await renderWorkflows();if(id)await openWorkflow(id)}catch(e){toast(e.message,'err')}finally{workflowLoading=false;var current=document.getElementById('workflow-create-button');if(current){current.disabled=false;current.textContent='创建并进入流程'}}};
function findWorkflowScalar(value,keys,depth){if(depth>5||value==null)return undefined;if(Array.isArray(value)){for(var i=0;i<value.length;i++){var fromArray=findWorkflowScalar(value[i],keys,depth+1);if(fromArray!==undefined)return fromArray}return undefined}if(typeof value!=='object')return undefined;for(var k=0;k<keys.length;k++){var direct=value[keys[k]];if(direct!==undefined&&direct!==null&&(typeof direct!=='object'||Array.isArray(direct)))return direct}var names=Object.keys(value);for(var n=0;n<names.length;n++){var nested=findWorkflowScalar(value[names[n]],keys,depth+1);if(nested!==undefined)return nested}return undefined}
function workflowStepFacts(step){var source=step.result_summary||{},sets={create_loan_application:[['申请状态',['application_status']],['写入结果',['operation']]],request_credit_report:[['征信报告',['report_id']],['供应商模式',['provider_mode']]],request_fraud_report:[['反欺诈结果',['fraud_result','result']],['欺诈评分',['fraud_score']]],generate_risk_assessment:[['风险等级',['risk_level']],['核验结论',['check_result']],['PD 代理值',['pd_value']]],create_phone_verification_task:[['电核任务',['verification_id']],['投递状态',['dispatch_status']]],record_phone_verification:[['电核结论',['conclusion']],['记录状态',['record_status']]],trigger_manual_review:[['路由结果',['routing_result']],['申请状态',['application_status']]],record_decision_recommendation:[['建议结果',['recommended_decision']],['决策边界',['decision_authority']]]},items=sets[step.action_name]||[];return items.map(function(item){var value=findWorkflowScalar(source,item[1],0);if(value===undefined||value===null||value==='')return '';if(Array.isArray(value))value=value.join('、');return '<span class="workflow-fact"><small>'+esc(item[0])+'</small><b>'+esc(value)+'</b></span>'}).filter(Boolean).join('')}
function workflowActionLabel(action){var definition=workflowActionDefinition(action);return definition.label||action}
function workflowDependencyText(action){var definition=workflowActionDefinition(action),deps=definition.dependencies||[];return deps.length?'前置：'+deps.map(workflowActionLabel).join('、'):'流程起点'}
